(6851691, 1031103, 23484, '<td valign="top">I like this image but I think a little more contrast would give it a boost. Just my opinion. Nice shot.</td>', 'I like this image but I think a little more contrast would give it a boost. Just my opinion. Nice shot.', '2012-08-29 11:43:52.000000', NULL, 1),
(6851694, 1031430, 23484, '<td valign="top">Wow, this is excellent. The strong contrast and depth of field really make this pop.10</td>', 'Wow, this is excellent. The strong contrast and depth of field really make this pop.10', '2012-08-29 11:44:57.000000', NULL, 1),
(6851712, 1031606, 12611, '<td valign="top">I like the lines, perhaps a bit "overcooked."<br/> <br/>eta: having looked again it is timeless and dreamy, and a good composition. <br/><br/><i>Message edited by author 2012-09-05 08:48:26.</i></td>', 'I like the lines, perhaps a bit "overcooked." eta: having looked again it is timeless and dreamy, and a good composition. ', '2012-08-29 12:06:17.000000', '2012-09-05 09:48:26.000000', 1),
(6851713, 1031536, 94134, '<td valign="top">Choas</td>', 'Choas', '2012-08-29 12:06:21.000000', NULL, 1),
(6851714, 1031358, 12611, '<td valign="top">Great movie, even the remake. The vignetting feel creates a bit of panic claustrophobia, but I like the textures.</td>', 'Great movie, even the remake. The vignetting feel creates a bit of panic claustrophobia, but I like the textures.', '2012-08-29 12:07:32.000000', NULL, 1),
(6851715, 1031536, 12611, '<td valign="top">Its like a "welcome to the future" shot. Look at the mess of concrete and metal civilization has, and will, become.</td>', 'Its like a "welcome to the future" shot. Look at the mess of concrete and metal civilization has, and will, become.', '2012-08-29 12:10:46.000000', NULL, 1),
(6851717, 1030949, 94134, '<td valign="top">Vintage, lovely</td>', 'Vintage, lovely', '2012-08-29 12:12:15.000000', NULL, 1),
(6851718, 1031607, 12611, '<td valign="top">There is a nice, positive feeling to this. I want to think its sunrise, something so hopeful and inspiring about a great sunrise.</td>', 'There is a nice, positive feeling to this. I want to think its sunrise, something so hopeful and inspiring about a great sunrise.', '2012-08-29 12:12:16.000000', NULL, 1),
(6851719, 1031360, 94134, '<td valign="top">Aerosmith reference?</td>', 'Aerosmith reference?', '2012-08-29 12:13:16.000000', NULL, 1),
(6851720, 1031483, 12611, '<td valign="top">First off, have to love umbrellas. Best prop ever. Secondly, the background blur is very interesting, as is the palm tree. Finally, the blue tonal edge works well.</td>', 'First off, have to love umbrellas. Best prop ever. Secondly, the background blur is very interesting, as is the palm tree. Finally, the blue tonal edge works well.', '2012-08-29 12:14:50.000000', NULL, 1),
(6851722, 1031137, 12611, '<td valign="top">The desat is nice. I understand the portrait aspect, but its leading lines to nowhere, so a squarer crop may have helped and reinforced the flag.</td>', 'The desat is nice. I understand the portrait aspect, but its leading lines to nowhere, so a squarer crop may have helped and reinforced the flag.', '2012-08-29 12:16:44.000000', NULL, 1),
(6851727, 1031587, 103759, '<td valign="top">very nice...love the reflections of the wheels...</td>', 'very nice...love the reflections of the wheels...', '2012-08-29 12:30:12.000000', NULL, 1),
(6851728, 1031359, 12611, '<td valign="top">I like the darkness and wet windows, well played.</td>', 'I like the darkness and wet windows, well played.', '2012-08-29 12:31:31.000000', NULL, 1),
(6851729, 1031571, 12611, '<td valign="top">Lensbaby adds some nice movement here.</td>', 'Lensbaby adds some nice movement here.', '2012-08-29 12:31:58.000000', NULL, 1),
(6851731, 1031231, 12611, '<td valign="top">Nice blue tone, and imposing architectural frame...</td>', 'Nice blue tone, and imposing architectural frame...', '2012-08-29 12:32:49.000000', NULL, 1),
(6851732, 1031526, 12611, '<td valign="top">I like the color scheme achieved through the processing here.</td>', 'I like the color scheme achieved through the processing here.', '2012-08-29 12:33:24.000000', NULL, 1),
(6851734, 1031612, 12611, '<td valign="top">I like how the tracks become a pair of lines and light. ( I am tempted to make associations but will withhold further comments.)</td>', 'I like how the tracks become a pair of lines and light. ( I am tempted to make associations but will withhold further comments.)', '2012-08-29 12:40:02.000000', NULL, 1),
(6851735, 1031431, 12611, '<td valign="top">Great color. You took an otherwise non-photogenic bridge and made it beautiful.</td>', 'Great color. You took an otherwise non-photogenic bridge and made it beautiful.', '2012-08-29 12:40:55.000000', NULL, 1),
(6851751, 1031360, 12611, '<td valign="top">On its surface this seems posed and contrived but there is a nice quality to the processing, the blur creates a pleasing feeling of movement which overcomes the Aerosmith reference and cheesy-rock band photo op feel which would have otherwise predominated.</td>', 'On its surface this seems posed and contrived but there is a nice quality to the processing, the blur creates a pleasing feeling of movement which overcomes the Aerosmith reference and cheesy-rock band photo op feel which would have otherwise predominated.', '2012-08-29 12:57:16.000000', NULL, 1),
(6851753, 1031455, 152079, '<td valign="top">Possibly crop the pic so that the no trespassing sign takes up a little more real estate? Just a personal thought on an otherwise nice photo.</td>', 'Possibly crop the pic so that the no trespassing sign takes up a little more real estate? Just a personal thought on an otherwise nice photo.', '2012-08-29 12:58:06.000000', NULL, 1),
(6851755, 1031530, 152079, '<td valign="top">Let the train come past the side rail, so you get the train, and the long shot of the bridge as well. Looks like a brave position to take a shot from!</td>', 'Let the train come past the side rail, so you get the train, and the long shot of the bridge as well. Looks like a brave position to take a shot from!', '2012-08-29 13:00:00.000000', NULL, 1),
(6851757, 1031246, 152079, '<td valign="top">Always like the "near the rails" perspective. Looks dangerous.</td>', 'Always like the "near the rails" perspective. Looks dangerous.', '2012-08-29 13:01:33.000000', NULL, 1),
(6851762, 1031330, 152079, '<td valign="top">If the shadow against the tracks is the main focus of your image, perhaps use a more extreme angle or move the shadow closer to the thirds lines? More contrast too would help.</td>', 'If the shadow against the tracks is the main focus of your image, perhaps use a more extreme angle or move the shadow closer to the thirds lines? More contrast too would help.', '2012-08-29 13:06:47.000000', NULL, 1),
(6851763, 1031487, 152079, '<td valign="top">Good solid shot.</td>', 'Good solid shot.', '2012-08-29 13:08:13.000000', NULL, 1),
(6851765, 1030983, 152079, '<td valign="top">More saturation and increased hilights would make this image pop.</td>', 'More saturation and increased hilights would make this image pop.', '2012-08-29 13:09:14.000000', NULL, 1),
(6851766, 1031465, 152079, '<td valign="top">How about a shot with the carriage in focus?</td>', 'How about a shot with the carriage in focus?', '2012-08-29 13:10:10.000000', NULL, 1),
