(6851774, 1031524, 152079, '<td valign="top">Too contrasty, you lose your subject a little in the background. Unless that was what you were going for? Try a low aperture number to blur out the background. You still get that pop of color, but them your subject stands out more.</td>', 'Too contrasty, you lose your subject a little in the background. Unless that was what you were going for? Try a low aperture number to blur out the background. You still get that pop of color, but them your subject stands out more.', '2012-08-29 13:19:20.000000', NULL, 1),
(6851775, 1031576, 152079, '<td valign="top">Always liked this technique.</td>', 'Always liked this technique.', '2012-08-29 13:20:01.000000', NULL, 1),
