(6856805, 1031431, 142473, '<td valign="top">Great lines and composition.  Wonderful colors.  Looks a bit over sharpened in some of the distant areas, but overall really nice.  Congratulations on the win.</td>', 'Great lines and composition.  Wonderful colors.  Looks a bit over sharpened in some of the distant areas, but overall really nice.  Congratulations on the win.', '2012-09-05 11:31:33.000000', NULL, 0),
