INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6858342, 1031518, 117534, '<td valign="top">Well next time I guess I should say top 2 or blue... Congrats it is a stunning shot!!</td>', 'Well next time I guess I should say top 2 or blue... Congrats it is a stunning shot!!', '2012-09-06 15:19:28.000000', NULL, 0),
(6858361, 1031576, 117534, '<td valign="top">slapping self for not pegging you on this one</td>', 'slapping self for not pegging you on this one', '2012-09-06 15:40:46.000000', NULL, 0),
(6858381, 1031179, 117534, '<td valign="top">I gave this a 5 in the voteing, it''s not a bad shot, it just doesn''t grab me, Snaffels nailed it needing something to engage me a little more.. I think even cropping so there is no gravel leading up to the bridge is more intrestring. Put your hand over the buildings on the right and the gravel, to me that is the crop I would''ve used on this..  That and 5.00 will get you a cup of coffee!</td>', 'I gave this a 5 in the voteing, it''s not a bad shot, it just doesn''t grab me, Snaffels nailed it needing something to engage me a little more.. I think even cropping so there is no gravel leading up to the bridge is more intrestring. Put your hand over the buildings on the right and the gravel, to me that is the crop I would''ve used on this..  That and 5.00 will get you a cup of coffee!', '2012-09-06 16:00:28.000000', NULL, 0),
(6858384, 1031179, 123833, '<td valign="top">With a tighter crop and vintage B&amp;W PP it would have done better</td>', 'With a tighter crop and vintage B&W PP it would have done better', '2012-09-06 16:04:46.000000', NULL, 0),
(6858408, 1031179, 101702, '<td valign="top">Commenting for the critique thread - I see I have this a 5 in voting.<br/> <br/>For me the immediate turn off is the tilting horizon. I''m like the "level police". I''ll always knock a point off for what I perceive to be a lack of attention to detail. If it is an intentional tilt, I would expect it to be a little more exaggerated.<br/> <br/>I agree with the other comments about a tighter crop too... The signs on the right are quite distracting so I would crop in so they were out of shot.<br/> <br/>The leading lines are good, but for a shot like this I would prefer more front to back focus so a much smaller aperture.<br/> <br/>I also feel a slightly lower perspective would help so that there was more looking along the tracks rather than down at the tracks.<br/> <br/>I do like the topaz processing, I agree with you that it came out pretty good.</td>', 'Commenting for the critique thread - I see I have this a 5 in voting. For me the immediate turn off is the tilting horizon. I''m like the "level police". I''ll always knock a point off for what I perceive to be a lack of attention to detail. If it is an intentional tilt, I would expect it to be a little more exaggerated. I agree with the other comments about a tighter crop too... The signs on the right are quite distracting so I would crop in so they were out of shot. The leading lines are good, but for a shot like this I would prefer more front to back focus so a much smaller aperture. I also feel a slightly lower perspective would help so that there was more looking along the tracks rather than down at the tracks. I do like the topaz processing, I agree with you that it came out pretty good.', '2012-09-06 16:40:49.000000', NULL, 0),
(6858446, 1031359, 131284, '<td valign="top">Thanks for all the great comments and favourites (and to Ben for the unexpected Sterling Sturgeon), I realised I was skirting close to the DNMC mark with this entry so am not surprised by the result, in fact if anything I was expecting it to do worse. Admittedly I think this would have done better in the street photography challenge, although I''ve let my membership lapse for the time being so no go there (once I find the drive to start entering regularly again I''m sure I''ll renew). The comments are what I really enter for though and so this entry for me was a great success, so thanks again everyone.</td>', 'Thanks for all the great comments and favourites (and to Ben for the unexpected Sterling Sturgeon), I realised I was skirting close to the DNMC mark with this entry so am not surprised by the result, in fact if anything I was expecting it to do worse. Admittedly I think this would have done better in the street photography challenge, although I''ve let my membership lapse for the time being so no go there (once I find the drive to start entering regularly again I''m sure I''ll renew). The comments are what I really enter for though and so this entry for me was a great success, so thanks again everyone.', '2012-09-06 17:15:19.000000', NULL, 0),
(6858469, 1031179, 138630, '<td valign="top">I was another 5 in the scoring and I scored low in this challenge so that''s a good average score.  I noticed the horizon, a sensor dust spot to the left of the top of the bridge, and a slight halo, quite wide, from the processing.  I think Susan''s ideas are great - I entered a very average shot in this challenge, too, and was dying to have someone to people mine!</td>', 'I was another 5 in the scoring and I scored low in this challenge so that''s a good average score.  I noticed the horizon, a sensor dust spot to the left of the top of the bridge, and a slight halo, quite wide, from the processing.  I think Susan''s ideas are great - I entered a very average shot in this challenge, too, and was dying to have someone to people mine!', '2012-09-06 17:39:18.000000', NULL, 0),
(6858473, 1031431, 31409, '<td valign="top">Yay, one for Seattle! Excellent, Brent!! I like the ferry in it, gives it an added touch<br/></td>', 'Yay, one for Seattle! Excellent, Brent!! I like the ferry in it, gives it an added touch', '2012-09-06 17:50:32.000000', NULL, 0),
(6858474, 1031518, 31409, '<td valign="top">Glad this won, Frank!! Good stuff<br/></td>', 'Glad this won, Frank!! Good stuff', '2012-09-06 17:51:20.000000', NULL, 0),
